// KodBox AI writer: document drafts generated by RAG, saved as the logged-in user.
kodReady.push(function() {
    'use strict';
    var $=window.jQuery || window.$;
    if (!$ || !$('#airaglite-header').length || $('#airaglite-writer-open').length) return;
    var style=[
      '#airaglite-writer-overlay{position:fixed;inset:0;background:#0009;z-index:10020;display:none;align-items:center;justify-content:center}',
      '#airaglite-writer-dialog{background:#fff;color:#263247;width:min(940px,96vw);max-height:92vh;display:flex;flex-direction:column;border-radius:12px;overflow:hidden}',
      '#airaglite-writer-body{padding:16px 20px;overflow:auto;display:flex;flex-direction:column;gap:12px}',
      '#airaglite-writer-body label{display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:600}',
      '#airaglite-writer-body input,#airaglite-writer-body textarea{border:1px solid #cbd5e1;border-radius:6px;padding:8px;color:#263247;background:#fff;font-weight:400}',
      '#airaglite-writer-body textarea{min-height:100px;resize:vertical}',
      '#airaglite-writer-editor{font-family:Consolas,monospace;min-height:250px}',
      '#airaglite-writer-preview{border:1px solid #cbd5e1;border-radius:6px;padding:12px;max-height:350px;overflow:auto;overflow-wrap:anywhere}',
      '#airaglite-writer-preview table{border-collapse:collapse;width:100%;display:block;overflow:auto}',
      '#airaglite-writer-preview td,#airaglite-writer-preview th{border:1px solid #cbd5e1;padding:6px}',
      '#airaglite-writer-folders{max-height:220px;overflow:auto;background:#f8fafc;padding:10px;border:1px solid #cbd5e1;border-radius:6px}',
      '#airaglite-writer-folders button{display:block;border:0;background:transparent;color:#1754ac;padding:6px;cursor:pointer;text-align:left}',
      '.airaglite-writer-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}',
      '.airaglite-writer-primary{background:#2368d6;border:0;border-radius:6px;padding:9px 14px;color:#fff;cursor:pointer}',
      '.airaglite-writer-secondary{background:#fff;border:1px solid #cbd5e1;border-radius:6px;padding:8px;color:#334155;cursor:pointer}',
      '@media(max-width:640px){#airaglite-writer-body{padding:10px}}'
    ].join('');
    $('head').append($('<style>').text(style));
    var trigger=$('<button type="button" id="airaglite-writer-open">✍ AI 写文档</button>')
        .css({marginLeft:'auto',marginRight:'12px',border:'1px solid #cbd5e1',padding:'5px 9px',borderRadius:'6px',background:'#fff',color:'#1754ac'})
        .insertBefore('#airaglite-close');
    var overlay=$('<div id="airaglite-writer-overlay"></div>').appendTo('body');
    var dialog=$('<div id="airaglite-writer-dialog" role="dialog" aria-modal="true" aria-label="AI 写文档"></div>').appendTo(overlay);
    var bar=$('<div class="airaglite-writer-actions" style="padding:14px 20px;border-bottom:1px solid #e2e8f0"></div>').appendTo(dialog);
    $('<b>AI 写文档 · 先预览，后保存</b>').appendTo(bar);
    var close=$('<button class="airaglite-writer-secondary" type="button" style="margin-left:auto">关闭</button>').appendTo(bar);
    var body=$('<div id="airaglite-writer-body"></div>').appendTo(dialog);
    var title=$('<input type="text" maxlength="160" placeholder="例如：Cephadm 部署操作手册">')
        .appendTo($('<label>文档主题</label>').appendTo(body));
    var req=$('<textarea maxlength="2000" placeholder="例如：面向运维人员，包含步骤、风险和回滚方案"></textarea>')
        .appendTo($('<label>写作要求（可选）</label>').appendTo(body));
    var sourceLabel=$('<label style="display:flex;flex-direction:row;align-items:center;font-weight:400"></label>').appendTo(body);
    var useSources=$('<input type="checkbox">').appendTo(sourceLabel);
    sourceLabel.append(document.createTextNode('参考已有 KodBox 文档（检索片段将发送到已配置的 AI 模型）'));
    var row=$('<div class="airaglite-writer-actions"></div>').appendTo(body);
    var generate=$('<button class="airaglite-writer-primary" type="button">生成草稿</button>').appendTo(row);
    var message=$('<span role="status" style="font-size:13px"></span>').appendTo(row);
    var editor=$('<textarea id="airaglite-writer-editor" maxlength="50000"></textarea>')
        .appendTo($('<label>正文（可直接编辑 Markdown）</label>').appendTo(body));
    var previewBtn=$('<button class="airaglite-writer-secondary" type="button">预览排版</button>').appendTo(body);
    var preview=$('<div id="airaglite-writer-preview"></div>').hide().appendTo(body);
    var refs=$('<div style="font-size:12px;white-space:pre-wrap;color:#64748b"></div>').appendTo(body);
    var folderRow=$('<div class="airaglite-writer-actions"></div>').appendTo(body);
    var currentFolder=$('<span></span>').text('保存到：个人空间 / AI草稿（默认）').appendTo(folderRow);
    var folderButton=$('<button class="airaglite-writer-secondary" type="button">选择文件夹</button>').appendTo(folderRow);
    var folderPanel=$('<div id="airaglite-writer-folders"></div>').hide().appendTo(body);
    var actions=$('<div class="airaglite-writer-actions"></div>').appendTo(body);
    var format=$('<select aria-label="保存格式"><option value="md">Markdown (.md)</option><option value="docx">Word (.docx)</option></select>').appendTo(actions);
    var save=$('<button type="button" class="airaglite-writer-primary">确认保存新文档</button>').appendTo(actions);
    var open=$('<button type="button" class="airaglite-writer-secondary">打开刚保存的文件</button>').hide().appendTo(actions);
    var selected='AI草稿', lastRoute='';
    function info(text,error){ message.text(String(text||'')).css('color',error?'#b91c1c':'#475569'); }
    function request(method,payload,ok,fail) {
        if (!window.kodApi || typeof window.kodApi.requestSend!=='function') {info('KodBox API 尚未就绪',true);if(fail)fail();return;}
        try {
            window.kodApi.requestSend('plugin/aiRagLite/'+method,payload,function(response){
                if (!response || response.code===false || !response.data) {
                    info(response && typeof response.data==='string' ? response.data : '请求失败',true);if(fail)fail();return;
                }
                ok(response.data);
            });
        } catch(e) { info(e.message||String(e),true);if(fail)fail(); }
    }
    function browse(folder){
        folderPanel.empty().show().append($('<p>正在加载文件夹……</p>'));
        request('writerFolders',{folder:folder},function(data){
            var relative=String(data.folder||'');
            folderPanel.empty().append($('<p></p>').text('个人空间'+(relative?'/'+relative:'（根目录）')));
            $('<button type="button">选择当前目录</button>').appendTo(folderPanel).on('click',function(){
                selected=relative;
                currentFolder.text('保存到：个人空间'+(selected?'/'+selected:'（根目录）'));
                folderPanel.hide();
            });
            if (relative) $('<button type="button">返回上级</button>').appendTo(folderPanel).on('click',function(){
                var p=relative.split('/');p.pop();browse(p.join('/'));
            });
            var items=Array.isArray(data.folders)?data.folders:[];
            items.forEach(function(f){
                $('<button type="button"></button>').text('📁 '+String(f.name||'')).appendTo(folderPanel)
                    .on('click',function(){browse(String(f.folder||''));});
            });
            if (!items.length) $('<p>没有下级文件夹</p>').appendTo(folderPanel);
        });
    }
    folderButton.on('click',function(){ if(folderPanel.is(':visible'))folderPanel.hide();else browse(''); });
    trigger.on('click',function(){ overlay.css('display','flex');title.trigger('focus'); });
    close.on('click',function(){overlay.hide();folderPanel.hide();});
    overlay.on('click',function(e){if(e.target===overlay[0])overlay.hide();});
    $(document).on('keydown.airaglite-writer',function(e){if(e.key==='Escape'&&overlay.is(':visible'))overlay.hide();});
    generate.on('click',function(){
        var topic=String(title.val()||'').trim();
        if (topic.length<2){info('请输入至少两个字的主题',true);return;}
        generate.prop('disabled',true); info('正在生成草稿……');
        // Restore the button even if the transport reports an error.
        request('draft',{topic:topic,requirements:String(req.val()||''),
                use_sources:useSources.prop('checked')?'1':'0'},function(data){
            generate.prop('disabled',false);
            editor.val(String(data.content||''));lastRoute='';open.hide();
            var sources=Array.isArray(data.sources)?data.sources:[];
            refs.text('参考范围：'+String(data.source_note||'未提供')+
                (sources.length?'\n'+sources.map(function(s){return '['+s.id+'] '+s.path+' · '+s.location;}).join('\n'):''));
            info('草稿已生成；请检查并修改后再保存。'); previewBtn.trigger('click');
        },function(){generate.prop('disabled',false);});
    });
    previewBtn.on('click',function(){
        preview.empty().show();
        if(typeof window.aiRagLiteRenderMarkdown==='function')window.aiRagLiteRenderMarkdown(preview[0],String(editor.val()||''));
        else $('<pre></pre>').text(String(editor.val()||'')).appendTo(preview);
    });
    save.on('click',function(){
        var topic=String(title.val()||'').trim(),content=String(editor.val()||'');
        if(topic.length<2||!content.trim()){info('主题或正文为空',true);return;}
        if(content.length>50000){info('正文超过 50000 字符上限',true);return;}
        save.prop('disabled',true);info('正在通过当前 KodBox 账号保存……');
        request('saveDraft',{title:topic,content:content,format:format.val(),folder:selected},function(data){
            save.prop('disabled',false);
            lastRoute=/^#fileView&path=.{1,4900}$/.test(String(data.route||''))?String(data.route):'';
            info('保存成功：'+String(data.name||'新文档')+'。未覆盖原文件。');open.toggle(!!lastRoute);
        },function(){save.prop('disabled',false);});
    });
    open.on('click',function(){
        if(!lastRoute)return;
        var url=new URL(lastRoute,window.location.href);
        if(url.origin===window.location.origin)window.open(url.href,'_blank','noopener');
    });
});
